import { useId, useState, type ReactNode } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Rating.module.css'

export interface RatingProps {
  /** 0 is unrated. Read-only ratings take fractions, e.g. 4.5. */
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
  max?: number
  size?: 'sm' | 'md' | 'lg'
  /** Shows a rating rather than asking for one. */
  readOnly?: boolean
  disabled?: boolean
  /** Visible label; the group's name. */
  label?: ReactNode
  /** The name when there is no visible `label`. */
  'aria-label'?: string
  /** Submitted with a form. */
  name?: string
  /** How each value is spoken, e.g. `(n) => `${n} stars``. */
  getValueText?: (value: number, max: number) => string
  className?: string
}

const defaultText = (value: number, max: number) => `${value} out of ${max} stars`

export function Rating({
  value,
  defaultValue = 0,
  onValueChange,
  max = 5,
  size = 'md',
  readOnly = false,
  disabled = false,
  label,
  'aria-label': ariaLabel,
  name,
  getValueText = defaultText,
  className,
}: RatingProps) {
  const id = useId()
  const [state, setState] = useState(defaultValue)
  const current = Math.min(max, Math.max(0, value ?? state))
  const stars = Array.from({ length: max }, (_, i) => i + 1)
  const classes = cn(styles.rating, styles[size], className)

  // Read-only: one image with the value as its name; stars can be partly filled.
  if (readOnly) {
    return (
      <span className={classes}>
        {label && <span className={styles.label}>{label}</span>}
        <span role="img" aria-label={getValueText(current, max)} className={styles.stars}>
          {stars.map((n) => {
            const fill = Math.min(1, Math.max(0, current - (n - 1)))
            return (
              <span key={n} className={styles.star} aria-hidden="true">
                <Icon name="star" className={styles.empty} />
                <span className={styles.fill} style={{ inlineSize: `${fill * 100}%` }}>
                  <Icon name="star-filled" />
                </span>
              </span>
            )
          })}
        </span>
      </span>
    )
  }

  // Interactive: native radios, so arrows, Tab and form submission are the
  // browser's own. Each radio is visually hidden behind its star.
  return (
    <fieldset className={classes} disabled={disabled} aria-label={label ? undefined : ariaLabel}>
      {label && <legend className={styles.label}>{label}</legend>}
      <span className={styles.stars}>
        {stars.map((n) => (
          <label key={n} className={cn(styles.star, n <= current && styles.on)}>
            <input
              type="radio"
              className={styles.input}
              name={name ?? id}
              value={n}
              checked={n === Math.round(current)}
              aria-label={getValueText(n, max)}
              onChange={() => {
                setState(n)
                onValueChange?.(n)
              }}
            />
            <Icon name={n <= current ? 'star-filled' : 'star'} />
          </label>
        ))}
      </span>
    </fieldset>
  )
}

.rating {
  --rating-star: var(--space-6);
  --rating-on: var(--warning);
  --rating-off: var(--control-border);
  display: inline-flex;
  flex-direction: column;
  gap: var(--space-1-5);
  margin: 0;
  padding: 0;
  border: 0;
  min-inline-size: 0;
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--foreground);
}
.sm {
  --rating-star: var(--space-4);
}
.lg {
  --rating-star: var(--space-8);
}

.label {
  padding: 0;
  font-weight: 500;
}

.stars {
  display: inline-flex;
  /* 2px between stars: below the spacing scale on purpose, as on Tag. */
  gap: 2px;
}

/* Filled stars in the bright --warning amber (2.1:1 on white, below the
   3:1 for meaningful graphics: the filled vs outlined shape and the
   accessible name carry the score, not the fill colour). Empty stars
   are outlined in --control-border (3:1). */
.star {
  position: relative;
  display: inline-flex;
  font-size: var(--rating-star);
  color: var(--rating-off);
}
.on {
  color: var(--rating-on);
}

label.star {
  cursor: var(--cursor-button);
}

/* Hover previews the rating up to the star under the pointer, and only
   while the rating can be changed. The "on" selectors outrank the "off"
   one (each adds a pseudo-class to it), so the hovered star lights too. */
fieldset:enabled .stars:has(label.star:hover) label.star {
  color: var(--rating-off);
}
fieldset:enabled .stars:has(label.star:hover) label.star:has(~ label.star:hover),
fieldset:enabled .stars:has(label.star:hover) label.star:hover {
  color: var(--rating-on);
}

.input {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
  cursor: inherit;
}

.star:has(.input:focus-visible) {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

fieldset:disabled .star {
  opacity: 0.5;
  cursor: var(--cursor-disabled);
}

/* Read-only: an outlined star with a filled one clipped to the fraction. */
.fill {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  display: inline-flex;
  overflow: hidden;
  color: var(--rating-on);
}
.empty {
  color: var(--rating-off);
}
/* The filled star keeps its full size and is cut by the span, rather than
   shrinking into it. */
.fill > :global(svg) {
  flex-shrink: 0;
}

/* 16px stars grow a 44px target on coarse pointers. */
@media (pointer: coarse) {
  label.star::after {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: 44px;
    block-size: 44px;
    translate: -50% -50%;
  }
}
